"""Check native coverage, exact generated bytes and physical-key conflicts."""
from collections import Counter

from build_preset import OUTPUT, UNKNOWN, VANILLA_COUNT, build, inventory, render

mappings = build()
if OUTPUT.read_bytes() != render(mappings):
    raise SystemExit("Regenerate launcher/controls-preset.txt with build_preset.py")
for name, key, modifier in inventory()[:VANILLA_COUNT]:
    if mappings[name] != key or modifier not in (None, "NONE"):
        raise SystemExit(f"Base binding changed: {name}")
active = Counter(key for key in mappings.values() if key != UNKNOWN)
if any(n != 1 for n in active.values()):
    raise SystemExit(f"Conflicting physical keys: {[key for key, n in active.items() if n > 1]}")
print(f"PASS: {len(inventory())} native rows, {len(mappings)} preset keys, "
      f"{len(active)} active, {VANILLA_COUNT} base mappings preserved, zero shared keys or chords")
